mapper.delete:
DELETE previousInput
FROM tax_inputs previousInput
JOIN tax_inputs currentInput ON currentInput.TAX_INPUT_ID = #{taxInputId}
                           AND previousInput.TAX_YEAR = currentInput.TAX_YEAR
WHERE previousInput.USER_ID = #{userId}
  AND previousInput.SAVE_STATUS = 'SAVED'
  AND previousInput.TAX_INPUT_ID != #{taxInputId}

mapper.update:
UPDATE tax_inputs SET USER_ID = #{userId}, SAVE_STATUS = 'SAVED', UPDATED_AT = CURRENT_TIMESTAMP
WHERE TAX_INPUT_ID = #{taxInputId}
  AND (USER_ID IS NULL OR USER_ID = #{userId})
